set-variable.value:
@{
        var jwt = (Jwt)context.Variables["validated-jwt"];
        var version = jwt.Claims.GetValueOrDefault("ver", "");
        var tenantId = jwt.Claims.GetValueOrDefault("tid", "");
        var objectId = jwt.Claims.GetValueOrDefault("oid", "");
        var azp = jwt.Claims.GetValueOrDefault("azp", "");
        var appid = jwt.Claims.GetValueOrDefault("appid", "");
        var allowedClientId = "{{intably-frontend-client-id}}";
        var allowedTenantIds = "{{intably-allowed-tenant-ids}}"
            .Split(new [] { ',' }, StringSplitOptions.RemoveEmptyEntries)
            .Select(value => value.Trim())
            .ToArray();
        var consumerTenantId = "9188040d-6c67-4c5b-b112-36a304b66dad";

        Guid parsedTenantId;
        Guid parsedObjectId;
        if (!Guid.TryParse(tenantId, out parsedTenantId)
            || !Guid.TryParse(objectId, out parsedObjectId)
            || tenantId.Equals(consumerTenantId, StringComparison.OrdinalIgnoreCase)
            || !allowedTenantIds.Any(
                value => value.Equals(tenantId, StringComparison.OrdinalIgnoreCase)))
        {
            return false;
        }

        var expectedIssuer = version == "1.0"
            ? "https://sts.windows.net/" + tenantId + "/"
            : "https://login.microsoftonline.com/" + tenantId + "/v2.0";
        if (!jwt.Issuer.Equals(expectedIssuer, StringComparison.OrdinalIgnoreCase))
        {
            return false;
        }

        if (version == "2.0")
        {
            return azp.Equals(allowedClientId, StringComparison.OrdinalIgnoreCase)
                && (String.IsNullOrEmpty(appid)
                    || appid.Equals(allowedClientId, StringComparison.OrdinalIgnoreCase));
        }

        if (version == "1.0")
        {
            return appid.Equals(allowedClientId, StringComparison.OrdinalIgnoreCase)
                && (String.IsNullOrEmpty(azp)
                    || azp.Equals(allowedClientId, StringComparison.OrdinalIgnoreCase));
        }

        return false;
      }

@{
        var jwt = (Jwt)context.Variables["validated-jwt"];
        var email = jwt.Claims.GetValueOrDefault("preferred_username", "");
        if (String.IsNullOrWhiteSpace(email))
        {
            email = jwt.Claims.GetValueOrDefault("email", "");
        }
        if (String.IsNullOrWhiteSpace(email))
        {
            email = jwt.Claims.GetValueOrDefault("upn", "");
        }
        return email;
      }

when.condition:
@{
          if (!(bool)context.Variables["intably-identity-is-valid"])
          {
              return true;
          }

          var jwt = (Jwt)context.Variables["validated-jwt"];
          return String.IsNullOrWhiteSpace(jwt.Claims.GetValueOrDefault("name", ""))
              || String.IsNullOrWhiteSpace((string)context.Variables["intably-user-email"]);
        }
